CREATE TABLE public.study_threads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, title text NOT NULL DEFAULT 'Nueva conversación', updated_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.study_threads TO authenticated; GRANT ALL ON public.study_threads TO service_role;
ALTER TABLE public.study_threads ENABLE ROW LEVEL SECURITY;
CREATE POLICY thread_owner ON public.study_threads FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE TABLE public.study_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), thread_id uuid NOT NULL REFERENCES public.study_threads(id) ON DELETE CASCADE, user_id uuid NOT NULL, sdk_id text NOT NULL, message jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(thread_id, sdk_id));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.study_messages TO authenticated; GRANT ALL ON public.study_messages TO service_role;
ALTER TABLE public.study_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY message_owner ON public.study_messages FOR ALL TO authenticated USING (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.study_threads t WHERE t.id = thread_id AND t.user_id = auth.uid())) WITH CHECK (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.study_threads t WHERE t.id = thread_id AND t.user_id = auth.uid()));
CREATE TABLE public.study_deadlines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, title text NOT NULL, course text NOT NULL DEFAULT '', due_at timestamptz NOT NULL, priority text NOT NULL DEFAULT 'medium' CHECK(priority IN ('low','medium','high')), completed boolean NOT NULL DEFAULT false, notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.study_deadlines TO authenticated; GRANT ALL ON public.study_deadlines TO service_role;
ALTER TABLE public.study_deadlines ENABLE ROW LEVEL SECURITY;
CREATE POLICY deadline_owner ON public.study_deadlines FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE TABLE public.study_career_members (user_id uuid PRIMARY KEY, career text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.study_career_members TO authenticated; GRANT ALL ON public.study_career_members TO service_role;
ALTER TABLE public.study_career_members ENABLE ROW LEVEL SECURITY;
CREATE POLICY membership_owner ON public.study_career_members FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());
CREATE TABLE public.study_materials (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, career text NOT NULL, title text NOT NULL, course text NOT NULL DEFAULT '', description text NOT NULL DEFAULT '', url text, file_path text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, DELETE ON public.study_materials TO authenticated; GRANT ALL ON public.study_materials TO service_role;
ALTER TABLE public.study_materials ENABLE ROW LEVEL SECURITY;
CREATE POLICY career_read ON public.study_materials FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.study_career_members m WHERE m.user_id = auth.uid() AND m.career = study_materials.career));
CREATE POLICY career_insert ON public.study_materials FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.study_career_members m WHERE m.user_id = auth.uid() AND m.career = study_materials.career));
CREATE POLICY material_delete ON public.study_materials FOR DELETE TO authenticated USING (user_id = auth.uid());
CREATE TABLE public.study_checks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, topic text NOT NULL, notes text NOT NULL, minutes integer NOT NULL DEFAULT 25, questions jsonb NOT NULL, answers jsonb, score numeric, completed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.study_checks TO authenticated; GRANT ALL ON public.study_checks TO service_role;
ALTER TABLE public.study_checks ENABLE ROW LEVEL SECURITY;
CREATE POLICY check_owner ON public.study_checks FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE TABLE public.study_ai_access (id text PRIMARY KEY, reason text NOT NULL, status integer NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.study_ai_access TO service_role;
ALTER TABLE public.study_ai_access ENABLE ROW LEVEL SECURITY;
CREATE INDEX study_messages_thread_date ON public.study_messages(thread_id, created_at);
CREATE INDEX study_deadlines_user_due ON public.study_deadlines(user_id, due_at);
CREATE INDEX study_materials_career ON public.study_materials(career);
CREATE INDEX study_checks_user ON public.study_checks(user_id, created_at);